// The committed tokens.css and tokens.ts are what Style Dictionary builds from the two token files
// (M1 plan, T19 step 5; D26): the same build `pnpm tokens` runs, through `formatPlatform`, which
// writes nothing. So `pnpm test` (and CI's `check`) fails if someone edits a generated file by
// hand, forgets `pnpm tokens` after changing a token file, or breaks a contrast pair.
import { readFileSync } from "node:fs";
import { describe, expect, it, vi } from "vitest";
import { buildModelFrom, formatTokens, PATHS } from "./build.ts";
import { pairRatio } from "./contrast.ts";
import { COMMERCE, CONTRACT, SURFACES } from "./model.ts";

vi.setConfig({ testTimeout: 30_000 });

const built = await formatTokens();
const committed = {
  css: readFileSync(PATHS.css, "utf8"),
  ts: readFileSync(PATHS.ts, "utf8"),
};

describe("the committed files", () => {
  it("tokens.css is what the build gives; if not, run `pnpm tokens`", () => {
    expect(committed.css).toBe(built.css);
  });

  it("tokens.ts is what the build gives; if not, run `pnpm tokens`", () => {
    expect(committed.ts).toBe(built.ts);
  });

  it("both say they are generated", () => {
    expect(committed.css).toContain(
      "Generated by Style Dictionary through scripts/figma-tokens.ts",
    );
    expect(committed.ts).toContain(
      "Generated by Style Dictionary through scripts/figma-tokens.ts",
    );
  });
});

describe("tokens.css", () => {
  const css = committed.css;
  const root = css.slice(
    css.indexOf(":root {"),
    css.indexOf("@theme inline {"),
  );
  const theme = css.slice(css.indexOf("@theme inline {"));

  it("is light only", () => {
    expect(css).not.toMatch(
      /\.dark|prefers-color-scheme|data-theme|color-scheme/i,
    );
    expect(css.match(/:root \{/g)).toHaveLength(1);
  });

  it("declares every variable of shadcn's contract and every commerce token of SPEC §9.2", () => {
    for (const name of [...CONTRACT, ...COMMERCE]) {
      expect(root, `--${name} in :root`).toMatch(
        new RegExp(`^ {2}--${name}: `, "m"),
      );
      expect(theme, `--color-${name} in @theme inline`).toContain(
        `--color-${name}: var(--${name});`,
      );
    }
    for (const name of SURFACES)
      expect(root).toMatch(new RegExp(`^ {2}--${name}-foreground: `, "m"));
  });

  it("derives the radius scale from one --radius of 10 px", () => {
    expect(root).toContain("--radius: 0.625rem;");
    expect(theme).toContain("--radius-xs: calc(var(--radius) - 8px);");
    expect(theme).toContain("--radius-lg: var(--radius);");
    expect(theme).toContain("--radius-4xl: calc(var(--radius) + 16px);");
  });

  it("emits --spacing alone, and Tailwind's names for type, breakpoints and shadows", () => {
    expect(theme).toContain("--spacing: 0.25rem;");
    expect(theme).not.toMatch(/--spacing-/);
    expect(theme).toContain("--text-xs: 0.75rem;");
    expect(theme).toContain("--text-xs--line-height: 1rem;");
    expect(theme).toContain("--text-9xl: 8rem;");
    expect(theme).toContain("--font-weight-semibold: 600;");
    expect(theme).toContain("--breakpoint-md: 48rem;");
    // The kit's two-layer md shadow is Tailwind's own `shadow-md`.
    expect(theme).toContain(
      "--shadow-md: 0 4px 6px -1px #0000001a, 0 2px 4px -2px #0000001a;",
    );
    expect(theme).toContain("--shadow-2xs: 0 1px 1px 0 #0000000d;");
  });

  it("reads the font next/font sets, with the system stack T20 wrote", () => {
    expect(theme).toMatch(
      /--font-sans:\n {4}var\(--font-inter, ui-sans-serif\), system-ui, sans-serif,\n {4}"Apple Color Emoji", .*"Noto Color Emoji";\n/,
    );
  });

  it("writes the overrides with the kit's value beside them", () => {
    expect(root).toContain(
      "--input: var(--neutral-450); /* the kit: #e5e5e5 */",
    );
    expect(root).toContain(
      "--muted-foreground: var(--neutral-550); /* the kit: #737373 */",
    );
  });

  it("emits a primitive only where a semantic token reads it", async () => {
    const model = await buildModelFrom();
    const used = new Set(
      model.colors.flatMap((c) => (c.primitive ? [c.primitive] : [])),
    );
    expect(model.primitives.map((p) => p.name).sort()).toEqual(
      [...used].sort(),
    );
    for (const p of model.primitives)
      expect(root).toContain(`--${p.name}: ${p.value};`);
  });
});

describe("the greys of our own are the lightest that pass (D35)", () => {
  const grey = (step: number) =>
    `#${step.toString(16).padStart(2, "0").repeat(3)}`;

  it("neutral-450 reaches 3:1 on white and one step lighter does not", async () => {
    const { primitives } = await buildModelFrom();
    const value = primitives.find((p) => p.name === "neutral-450")!.value;
    expect(value).toBe(grey(0x94));
    expect(pairRatio(value, "#ffffff")).toBeGreaterThanOrEqual(3);
    expect(pairRatio(grey(0x95), "#ffffff")).toBeLessThan(3);
  });

  it("neutral-550 reaches 4.5:1 on muted and one step lighter does not", async () => {
    const { primitives, colors } = await buildModelFrom();
    const value = primitives.find((p) => p.name === "neutral-550")!.value;
    const muted = colors.find((c) => c.name === "muted")!.value;
    expect(value).toBe(grey(0x70));
    expect(pairRatio(value, muted)).toBeGreaterThanOrEqual(4.5);
    expect(pairRatio(grey(0x71), muted)).toBeLessThan(4.5);
  });

  it("at the 50 % alpha the kit draws a ring with, no grey lighter than #2a2a2a reaches 3:1", () => {
    expect(pairRatio(grey(0x2a), "#ffffff", 0.5)).toBeGreaterThanOrEqual(3);
    expect(pairRatio(grey(0x2b), "#ffffff", 0.5)).toBeLessThan(3);
  });
});

describe("the gate", () => {
  it("passes every declared pair, and each pair has a ratio in tokens.ts", async () => {
    const model = await buildModelFrom();
    expect(model.pairs.length).toBeGreaterThanOrEqual(30);
    for (const pair of model.pairs)
      expect(pair.ratio, pair.id).toBeGreaterThanOrEqual(pair.minimum);
    expect(committed.ts).toContain('id: "ui.input-on-background"');
  });

  it("checks the pairs D35 lists", async () => {
    const ids = (await buildModelFrom()).pairs.map((p) => p.id);
    for (const id of [
      "text.foreground-on-background",
      "text.card-foreground-on-card",
      "text.muted-foreground-on-muted",
      "text.muted-foreground-on-background",
      "text.price-on-background",
      "text.price-sale-on-background",
      "text.badge-sale-foreground-on-badge-sale",
      "text.stock-in-on-background",
      "text.stock-low-on-background",
      "text.stock-out-on-background",
      "ui.input-on-background",
      "ui.ring-on-background",
      "ui.primary-on-background",
    ])
      expect(ids).toContain(id);
  });

  it("does not check `border`, which D35 calls decorative", async () => {
    const ids = (await buildModelFrom()).pairs.map((p) => p.id);
    expect(ids.filter((id) => id.includes("border"))).toEqual([]);
  });

  it("overrides the kit in seven places, each with the kit's ratio beside ours", async () => {
    const model = await buildModelFrom();
    const overridden = model.colors
      .filter((c) => c.override)
      .map((c) => c.name);
    expect(overridden).toEqual([
      "muted-foreground",
      "destructive-foreground",
      "input",
      "ring",
      "success",
      "warning",
      "info",
    ]);
    for (const pair of model.pairs) {
      const touches = [pair.foreground, pair.background, pair.over].some(
        (side) => side && overridden.includes(side.name),
      );
      expect(pair.kit !== undefined, pair.id).toBe(touches);
    }
    // An override exists because the kit's value fails a pair.
    for (const name of overridden) {
      const failing = model.pairs.filter(
        (p) =>
          [p.foreground, p.background, p.over].some(
            (side) => side?.name === name,
          ) && p.kit?.passes === false,
      );
      expect(failing.length, `the kit's ${name} fails no pair`).toBeGreaterThan(
        0,
      );
    }
  });
});
